-- V5_3（SQL Server）ログインに必要なデータだけになった M_APPLICANT を申込者アカウント（M_APPLICANT_ACCOUNT）に改名し、申込からの外部キーを張り直す
EXEC sp_rename 'M_APPLICANT', 'M_APPLICANT_ACCOUNT';
EXEC sp_rename 'PK_M_APPLICANT', 'PK_M_APPLICANT_ACCOUNT', 'OBJECT';
EXEC sp_rename 'UK_M_APPLICANT_01', 'UK_M_APPLICANT_ACCOUNT_01', 'OBJECT';
ALTER TABLE T_APPLICATION ADD CONSTRAINT FK_T_APPLICATION_APPLICANT FOREIGN KEY (APPLICANT_ID) REFERENCES M_APPLICANT_ACCOUNT (APPLICANT_ID);
